  "codebook": {
    "definition": "Credit-claiming is defined as any communication in which a member of Congress asserts personal responsibility, or joint responsibility with close colleagues or their state delegation, for causing a specific, completed, or officially approved positive outcome (such as securing federal funding, passing a law or amendment, enacting a regulatory exception, or resolving casework) that benefits their constituents or a specific aligned interest.",
    "clarification": "To qualify as credit-claiming, the senator must link a finalized or achieved success directly to their own actions (e.g., authoring, co-authoring, inserting amendments, writing official letters, lobbying agencies, or chairing key proceedings). Merely introducing a bill, sponsoring a pending measure, voting, or expressing general support does not count. The outcome must be presented as successfully completed, approved, or established.",
    "positive_examples": [
      {
        "document_id": "1862",
        "explanation": "The senators explicitly claim that they 'delivered on their promise to secure federal funding' ($12.5 million for Butte) in the Defense Appropriations Bill."
      },
      {
        "document_id": "2382",
        "explanation": "The senator details her direct casework success by explaining how she personally 'ensured that Rayan... was able to come to the United States' by 'intervening with the Department of Homeland Security and removing bureaucratic red tape.'"
      },
      {
        "document_id": "2627",
        "explanation": "The senator explicitly claims credit for securing a $1.5 million appropriation for a health sciences facility at the University of Missouri-Columbia by announcing the Senate approved 'his request' for the funds."
      }
    ],
    "negative_clarification": "Do not classify a text as credit-claiming if it only features position-taking, partisan policy debates, generic voting explanations, expressions of grief or commemorative statements, announcements of future events (like town halls), or casework/advocacy that is still in progress without a finalized positive outcome.",
    "negative_examples": [
      {
        "document_id": "57",
        "explanation": "The senator is introducing a new piece of legislation that has not yet passed. This represents standard legislative position-taking, as no positive legislative outcome has been completed yet."
      },
